/* Pure arithmetic (patterns, convolution, pooling, costs, receptive fields) lives in cnn-math.js. */
function cnnPlayColour(value,maxAbs,input=false,padding=false){
  if(padding)return "#e7edf2";
  if(input){const amount=clamp(value,0,1);return `rgb(${Math.round(246-170*amount)},${Math.round(249-126*amount)},${Math.round(251-80*amount)})`}
  const amount=clamp(Math.abs(value)/(maxAbs||1),0,1),target=value>=0?[36,110,170]:[226,120,53],base=[247,249,250],mix=.12+.78*amount;
  return `rgb(${target.map((channel,index)=>Math.round(base[index]*(1-mix)+channel*mix)).join(",")})`;
}

/* Channel tint for the multi-channel view (the R/G/B labels carry the meaning; colour is a secondary cue). */
function cnnChannelColour(value,tint){const target={red:[196,75,75],green:[35,132,93],blue:[36,110,170]}[tint],base=[247,249,250],mix=clamp(value,0,1)*.85;return `rgb(${target.map((channel,index)=>Math.round(base[index]*(1-mix)+channel*mix)).join(",")})`}
window.LAB_GUIDE_VARIANT=window.LAB_GUIDE_VARIANT||{};
window.LAB_GUIDE_VARIANT.cnn=()=>activeConcept==="cnn"&&conceptState?conceptState.view:null;

