  conceptState={view:"pipeline",pattern:"edge",lastPattern:"edge",pixels:cnnPlayPattern("edge"),kernelName:"vertical",kernel:cnnPlayClone(CNN_PLAY_KERNELS.vertical),padding:0,stride:1,dilation:1,activation:"relu",pool:"max",position:2,inputArea:null,mapAreas:[],channels:1,colour:"gray",colourChannels:null,extraSlices:[cnnPlayClone(CNN_PLAY_KERNELS.vertical),cnnPlayClone(CNN_PLAY_KERNELS.vertical)],sliceNames:["vertical","vertical","vertical"],editChannel:0,filters:1,bias:0,explanationKey:"base",layers:2,poolBetween:0,depthSel:null,depthSig:""};
