  const syncKernelInputs=()=>{const label=$("#cnnWeightsLabel");if(label)label.textContent=multiChannel()?`Editable 3 × 3 weights · ${["red","green","blue"][conceptState.editChannel]} slice`:"Editable 3 × 3 weights";$("#cnnKernel").value=editingExtra()?conceptState.sliceNames[conceptState.editChannel]:conceptState.kernelName;const target=editTarget();document.querySelectorAll("[data-cnn-weight]").forEach(input=>{const index=Number(input.dataset.cnnWeight),value=target[Math.floor(index/3)][index%3];input.value=String(Math.round(value*1000)/1000);input.style.background=value>0?"#e4f0f8":value<0?"#fff0e6":"#fff"})};
