  const matrixGeometry=(matrix,centerX,y,maxWidth,maxHeight,maxCell=28)=>{const rows=matrix.length,columns=matrix[0].length,cell=Math.max(rows>9||columns>9?3:8,Math.min(maxCell,maxWidth/columns,maxHeight/rows)),width=columns*cell,height=rows*cell;return {x:centerX-width/2,y,w:width,h:height,cell,rows,columns}};
